import * as THREE from 'three';
import {createDormiPoser} from '../dormi-poses.js';
import {createPhotoCompanion,disposePhotoCompanion} from './photo-cast.js';
import {photoCast,PHOTO_BACKGROUNDS,PHOTO_POSES} from './photo-config.js';
import {disposeToyTree} from '../world/toy-kit.js';
import {buildPhotoRig,posePhotoParticipants} from './photo-rig.js';
export function clonePhotoModel(source){const root=source.clone(true);root.position.set(0,0,0);root.rotation.set(0,0,0);root.traverse(o=>{if(o.isMesh){o.geometry=o.geometry.clone();o.material=Array.isArray(o.material)?o.material.map(m=>m.clone()):o.material.clone();}});return root;}
/** Owned offline/test composition using the exact room rig; the game never creates a second studio. */
export function buildPhotoComposition(dormi,companion,config){const scene=new THREE.Scene(),root=new THREE.Group();scene.add(root);const rig=buildPhotoRig(root),poser=createDormiPoser(dormi),snapshot=posePhotoParticipants({rig,dormi,poser,...(Array.isArray(companion)?{companions:companion}:{companion}),config});scene.background=new THREE.Color('#d7e4df');scene.add(new THREE.HemisphereLight('#fbfff3','#aab39b',2.6));const sun=new THREE.DirectionalLight('#fff0d4',4.3);sun.position.set(-3,9,7);scene.add(sun);const fill=new THREE.DirectionalLight('#d8e9ff',1.2);fill.position.set(4,5,-3);scene.add(fill);scene.updateMatrixWorld(true);let disposed=false;return {scene,root,rig,camera:rig.camera,snapshot,dispose(){if(disposed)return;disposed=true;poser.dispose();for(const actor of (Array.isArray(companion)?companion:companion?[companion]:[]))disposePhotoCompanion(actor);disposeToyTree(root);scene.clear();}};}
/** Borrow the real scene/player/poser. Only the temporary approved companion is session-owned. */
export function createPhotoSession({scene,studioView,player,model,poser,companionFactory=createPhotoCompanion,onActive=()=>{}}){
 const rig=studioView?.villageView?.photoRig??studioView?.photoRig;if(!rig||!player||!poser)throw Error('NoStudioRig');
 const saved={parent:player.parent,position:player.position.clone(),quaternion:player.quaternion.clone(),scale:player.scale.clone(),modelPosition:model?.position.clone(),modelQuaternion:model?.quaternion.clone(),pose:poser.getState(),children:player.children.map(o=>[o,o.visible]),ambientResidents:[...(studioView.shopResidentModels?.values()??[])].map(o=>[o,o.visible])};
 let alive=true,generation=0,companions=[],snapshot=null;onActive(true);for(const [resident]of saved.ambientResidents)resident.visible=false;if(model){model.position.set(0,0,0);model.rotation.set(0,0,0);}for(const child of player.children)if(child!==model)child.visible=false;
 function dispose(){if(!alive)return;alive=false;generation++;companions.forEach(disposePhotoCompanion);companions=[];saved.parent.add(player);player.position.copy(saved.position);player.quaternion.copy(saved.quaternion);player.scale.copy(saved.scale);if(model){model.position.copy(saved.modelPosition);model.quaternion.copy(saved.modelQuaternion);}poser.setPose(saved.pose.name,saved.pose.amount,saved.pose.time);for(const [child,visible] of saved.children)child.visible=visible;for(const [resident,visible]of saved.ambientResidents)resident.visible=visible;rig.setConfig();scene.updateMatrixWorld(true);onActive(false);}
 return {scene,camera:rig.camera,rig,async update(config){const ids=photoCast(config);if(!ids||!Object.hasOwn(PHOTO_BACKGROUNDS,config.background)||!Object.hasOwn(PHOTO_POSES,config.pose))throw Error('Invalid photo choices');const token=++generation;const settled=await Promise.allSettled(ids.map(id=>companionFactory(id,{showBook:false})));const next=settled.filter(r=>r.status==='fulfilled').map(r=>r.value);if(!alive||token!==generation){next.forEach(disposePhotoCompanion);return false;}if(settled.some(r=>r.status==='rejected')){next.forEach(disposePhotoCompanion);throw Error('Photo companion loading failed');}try{const shot=posePhotoParticipants({rig,dormi:player,poser,companions:next,config});companions.forEach(disposePhotoCompanion);companions=next;snapshot=shot;scene.updateMatrixWorld(true);return true;}catch(error){next.forEach(disposePhotoCompanion);dispose();throw error;}},getSnapshot(){return snapshot?structuredClone(snapshot):null;},dispose};
}
export async function createPhotoPreview(canvas,{onFailure,session}={}){
 if(!session)throw Error('NoLivePhotoSession');let renderer,alive=true;try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,preserveDrawingBuffer:false,powerPreference:'low-power'});renderer.setPixelRatio(1);renderer.setSize(640,480,false);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.22;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;}catch(error){session.dispose();throw error;}
 function render(){const hidden=[session.rig.lens,session.rig.tripod],visible=hidden.map(o=>o.visible);hidden.forEach(o=>o.visible=false);try{renderer.render(session.scene,session.camera);}finally{hidden.forEach((o,i)=>o.visible=visible[i]);}}
 const contextLost=e=>{e.preventDefault();dispose();onFailure?.();};canvas.addEventListener('webglcontextlost',contextLost);
 function dispose(){if(!alive)return;alive=false;session.dispose();canvas.removeEventListener('webglcontextlost',contextLost);renderer.renderLists.dispose();renderer.dispose();renderer.forceContextLoss();}
 return {async update(config){const done=await session.update(config);if(!alive||!done)return false;render();return true;},capture(){if(!alive||!session.getSnapshot())throw Error('NoPhotoScene');render();let data=canvas.toDataURL('image/jpeg',.82);if(data.length>140000)data=canvas.toDataURL('image/jpeg',.65);if(data.length>140000)throw Error('PhotoTooLarge');return data;},getSnapshot:session.getSnapshot,dispose};
}
